import React from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';
import Login from './components/Login';
import Layout from './components/Layout';
import Dashboard from './components/Dashboard';
import Correos from './components/Correos';
import CargarCSV from './components/CargarCSV';
import EnviarCorreos from './components/EnviarCorreos';
import Campanas from './components/Campanas';
import Logs from './components/Logs';
import ConfiguracionSMTP from './components/ConfiguracionSMTP';
import EquiposInventario from './components/EquiposInventario';
import MemoriasRAM from './components/MemoriasRAM';
import AlmacenamientoInv from './components/AlmacenamientoInv';
import SalidaBodega from './components/SalidaBodega';

// Protected Route Component
const ProtectedRoute = ({ children }) => {
  const { isAuthenticated, loading } = useAuth();
  
  if (loading) {
    return (
      <div className="loading-spinner">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Cargando...</span>
        </div>
      </div>
    );
  }
  
  if (!isAuthenticated) {
    return <Navigate to="/login" replace />;
  }
  
  return <Layout>{children}</Layout>;
};

// Public Route Component (redirects to dashboard if authenticated)
const PublicRoute = ({ children }) => {
  const { isAuthenticated, loading } = useAuth();
  
  if (loading) {
    return (
      <div className="loading-spinner">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Cargando...</span>
        </div>
      </div>
    );
  }
  
  if (isAuthenticated) {
    return <Navigate to="/dashboard" replace />;
  }
  
  return children;
};

function App() {
  return (
    <AuthProvider>
      <BrowserRouter future={{ v7_startTransition: true, v7_relativeSplatPath: true }}>
        <Routes>
          {/* Public Routes */}
          <Route
            path="/login"
            element={
              <PublicRoute>
                <Login />
              </PublicRoute>
            }
          />
          
          {/* Protected Routes */}
          <Route
            path="/dashboard"
            element={
              <ProtectedRoute>
                <Dashboard />
              </ProtectedRoute>
            }
          />
          <Route
            path="/correos"
            element={
              <ProtectedRoute>
                <Correos />
              </ProtectedRoute>
            }
          />
          <Route
            path="/cargar"
            element={
              <ProtectedRoute>
                <CargarCSV />
              </ProtectedRoute>
            }
          />
          <Route
            path="/enviar"
            element={
              <ProtectedRoute>
                <EnviarCorreos />
              </ProtectedRoute>
            }
          />
          <Route
            path="/campanas"
            element={
              <ProtectedRoute>
                <Campanas />
              </ProtectedRoute>
            }
          />
          <Route
            path="/logs"
            element={
              <ProtectedRoute>
                <Logs />
              </ProtectedRoute>
            }
          />
          <Route
            path="/configuracion-smtp"
            element={
              <ProtectedRoute>
                <ConfiguracionSMTP />
              </ProtectedRoute>
            }
          />
          
          {/* Default Redirect */}
          <Route path="/" element={<Navigate to="/dashboard" replace />} />
          <Route path="*" element={<Navigate to="/dashboard" replace />} />
        </Routes>
      </BrowserRouter>
    </AuthProvider>
  );
}

export default App;
